// Controlled deployment test (mandate section 14 part 2) through chat→worker path.
// Submits a chat prompt that requires a real, harmless, production-visible change:
// bump the IVX_SENIOR_DEV_WORKER_MARKER date from 2026-07-17 → 2026-07-19.
// This forces the worker to: edit file → commit → push → deploy → verify /health →
// confirm live commit == GitHub HEAD → return proof in chat.
const BASE = "https://api.ivxholding.com";
const token = await Bun.file("/tmp/owner_at").text();

const prompt = [
  "Controlled deployment test (owner-authorized).",
  "Bump the production-visible version marker IVX_SENIOR_DEV_WORKER_MARKER in backend/services/ivx-senior-developer-worker.ts from 'ivx-senior-developer-worker-2026-07-17' to 'ivx-senior-developer-worker-2026-07-19' (today's date).",
  "Then commit the change to GitHub main, trigger a Render deploy, wait for LIVE, call /health, and confirm the live runtime commit SHA equals GitHub HEAD.",
  "Return verified evidence: commit SHA, deploy ID, /health response, live commit, GitHub HEAD, and whether they match.",
  "This is a harmless version-marker bump — no business logic changes.",
].join(" ");

console.log("=== CONTROLLED DEPLOYMENT TEST VIA CHAT ===");
console.log("Prompt length:", prompt.length, "chars");

const t0 = Date.now();
const r = await fetch(BASE + "/api/ivx/owner-ai", {
  method: "POST",
  headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
  body: JSON.stringify({
    message: prompt,
    requestId: "controlled-deploy-test-" + Date.now(),
    confirm: true,
    confirmText: "CONFIRM_IVX_GITHUB_WRITE",
  }),
});
const elapsed = Date.now() - t0;
const text = await r.text();
console.log("HTTP status:", r.status, "(elapsed " + elapsed + "ms)");

let j: any;
try { j = JSON.parse(text); } catch { j = { raw: text.slice(0, 3000) }; }

const answer = j.answer || j.response || j.message || (typeof j === "string" ? j : JSON.stringify(j).slice(0, 3000));
console.log("\n=== CHAT ANSWER (first 4000 chars) ===");
console.log(typeof answer === "string" ? answer.slice(0, 4000) : JSON.stringify(answer).slice(0, 4000));

// Extract task ID
const tidMatch = typeof answer === "string" ? answer.match(/ivx-worker-[a-f0-9-]{36}/) : null;
const taskId = tidMatch ? tidMatch[0] : null;
console.log("\n=== EXTRACTED TASK ID ===");
console.log("taskId:", taskId);

// Extract commit SHA
const shaMatch = typeof answer === "string" ? answer.match(/\b([a-f0-9]{40})\b/) : null;
const commitSha = shaMatch ? shaMatch[1] : null;
console.log("commitSha in answer:", commitSha);

// Save evidence
const evidence = {
  testTimestamp: new Date().toISOString(),
  testType: "controlled_deployment_via_chat",
  prompt,
  chatHttpStatus: r.status,
  chatElapsedMs: elapsed,
  taskId,
  commitShaInAnswer: commitSha,
  answerPreview: typeof answer === "string" ? answer.slice(0, 4000) : null,
};
await Bun.file("/tmp/controlled-deploy-test-evidence.json").write(JSON.stringify(evidence, null, 2));
console.log("\nEvidence saved to /tmp/controlled-deploy-test-evidence.json");

// If we got a task ID, poll the job status
if (taskId) {
  console.log("\n=== POLLING JOB STATUS ===");
  for (let i = 0; i < 8; i++) {
    await new Promise((r) => setTimeout(r, 5000));
    const jr = await fetch(BASE + "/api/ivx/senior-developer/worker/jobs/" + taskId, {
      headers: { Authorization: "Bearer " + token },
    });
    const jj = await jr.json();
    const job = jj.job || jj;
    console.log("[" + (i+1) + "] status=" + job.status + " stage=" + job.stage + " progress=" + job.progressPercent + "% commitSha=" + (job.result?.commitSha || "null") + " deployId=" + (job.result?.deployId || "null") + " commitMatch=" + (job.result?.commitMatch ?? "null"));
    if (job.status === "completed" || job.status === "blocked" || job.status === "failed") {
      console.log("\n=== FINAL JOB RESULT ===");
      console.log(JSON.stringify(job.result, null, 2).slice(0, 3000));
      break;
    }
  }
}

