// Reproduce the router decision locally against the controlled-deploy prompt
// to pinpoint which branch captured it (and why it returned "The answer is 2019").
import { routeIVXChatIntent } from '../backend/services/ivx-chat-intent-router';
import { buildIVXOwnerAIPlannerDecision, isOwnerExecutionOrTaskBlock, shouldUseCurrentTimeTool, targetsOwnSystemBuild, demandsExecutionProofNotNarrative, isRemovalExecutionPrompt } from '../backend/services/ivx-owner-ai-intent-router';

const prompt = [
  "Controlled deployment test (owner-authorized).",
  "Bump the production-visible version marker IVX_SENIOR_DEV_WORKER_MARKER in backend/services/ivx-senior-developer-worker.ts from 'ivx-senior-developer-worker-2026-07-17' to 'ivx-senior-developer-worker-2026-07-19' (today's date).",
  "Then commit the change to GitHub main, trigger a Render deploy, wait for LIVE, call /health, and confirm the live runtime commit SHA equals GitHub HEAD.",
  "Return verified evidence: commit SHA, deploy ID, /health response, live commit, GitHub HEAD, and whether they match.",
  "This is a harmless version-marker bump — no business logic changes.",
].join(" ");

console.log("PROMPT (len=" + prompt.length + "):");
console.log(prompt);
console.log();

const planner = buildIVXOwnerAIPlannerDecision(prompt);
console.log("=== PLANNER ===");
console.log("route:", planner.route);
console.log("semanticIntent:", planner.semanticIntent);
console.log("fallbackPolicy:", planner.fallbackPolicy);
console.log();

console.log("=== HELPER FUNCTIONS ===");
console.log("isOwnerExecutionOrTaskBlock:", isOwnerExecutionOrTaskBlock(prompt));
console.log("shouldUseCurrentTimeTool:", shouldUseCurrentTimeTool(prompt));
console.log("targetsOwnSystemBuild:", targetsOwnSystemBuild(prompt.toLowerCase()));
console.log("demandsExecutionProofNotNarrative:", demandsExecutionProofNotNarrative(prompt.toLowerCase()));
console.log("isRemovalExecutionPrompt:", isRemovalExecutionPrompt(prompt.toLowerCase()));
console.log();

const unified = routeIVXChatIntent(prompt, false);
console.log("=== UNIFIED ROUTER ===");
console.log("branch:", unified.branch);
console.log("intent:", unified.intent);
console.log("mayExecuteSideEffects:", unified.mayExecuteSideEffects);
console.log("requiresOwnerSession:", unified.requiresOwnerSession);
console.log("hint:", unified.hint);
console.log("reason:", unified.reason);

