//   backend/services/ivx-owner-ai-intent-router.ts  (46KB → gzip-base64, >30KB)
//   backend/services/ivx-chat-intent-router.ts       (17KB → plain, <30KB)
const BASE = "https://api.ivxholding.com";
const OWNER = "iperez4242@gmail.com";

// Re-mint owner token
const lm = await fetch(BASE + "/api/ivx/owner-passwordless-login", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ email: OWNER }),
});
const lmj = await lm.json();
const token = lmj.accessToken;
await Bun.file("/tmp/owner_at").write(token);
console.log("Owner token minted, len=" + token.length);

const { deflateSync } = await import("node:zlib");

function gzipB64(buf) {
  return Buffer.from(deflateSync(buf)).toString("base64");
}

async function commitFile(path, content, message, useGzip) {
  const body = {
    action: "github_commit_file",
    input: useGzip
      ? { path, content: gzipB64(content), contentEncoding: "gzip-base64", message }
      : { path, content, message },
    confirm: true,
    confirmText: "CONFIRM_IVX_GITHUB_WRITE",
  };
  const r = await fetch(BASE + "/api/ivx/developer-deploy/action", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
    body: JSON.stringify(body),
  });
  const j = await r.json();
  const sha = j?.result?.commitSha;
  console.log(`\n=== COMMIT ${path} ${useGzip ? "(gzip-base64)" : "(plain)"} ===`);
  console.log("status=" + r.status + " commitSha=" + sha);
  if (!sha) console.log("response:", JSON.stringify(j).slice(0, 400));
  return sha;
}

