const f2 = await Bun.file("/home/user/rork-app/backend/services/ivx-chat-intent-router.ts").text();

const sha1 = await commitFile(
  "backend/services/ivx-owner-ai-intent-router.ts",
  f1,
  "chat→worker: isOwnerExecutionOrTaskBlock recognizes production-execution signals (commit+github/deploy+render/verify+/health/bump+version) so short-circuit gates can't hijack deploy prompts (fixes 'The answer is 2019' narrative fallback)",
  true,
);

const sha2 = await commitFile(
  "backend/services/ivx-chat-intent-router.ts",
  f2,
  "chat→worker: guard resolveOwnerBackendCommandLocal with !isOwnerExecutionOrTaskBlock so /time-now short-circuit can't hijack deploy/commit prompts before developer_executor branch",
  false,
);

const finalSha = sha2 || sha1;
console.log("\n=== FINAL HEAD: " + finalSha + " ===");

// Trigger deploy
const dr = await fetch(BASE + "/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
  body: JSON.stringify({ action: "render_trigger_deploy", input: {}, confirm: true, confirmText: "CONFIRM_IVX_RENDER_DEPLOY" }),
});
const dj = await dr.json();
console.log("\n=== RENDER DEPLOY ===");
console.log("status=" + dr.status + " deployId=" + dj?.result?.deployId + " status=" + dj?.result?.status);
