// Commit + deploy the third router fix: backend/api/ivx-owner-ai.ts (391KB → gzip-base64).
// This is the critical fix — resolveOwnerBackendCommand() now guards shouldUseCurrentTimeTool
// with isOwnerExecutionOrTaskBlock(prompt), so the /time-now short-circuit can't hijack
// clear deploy/commit/audit prompts before they reach the developer_executor branch at line 7173.
const BASE = "https://api.ivxholding.com";
const token = await Bun.file("/tmp/owner_at").text();

const { gzipSync } = await import("node:zlib");
const f = await Bun.file("/home/user/rork-app/backend/api/ivx-owner-ai.ts").text();
const encoded = Buffer.from(gzipSync(f)).toString("base64");
console.log("ivx-owner-ai.ts:", f.length, "bytes → gzip-base64", encoded.length, "chars");

const r = await fetch(BASE + "/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
  body: JSON.stringify({
    action: "github_commit_file",
    input: {
      path: "backend/api/ivx-owner-ai.ts",
      content: encoded,
      contentEncoding: "gzip-base64",
      message: "chat→worker: guard resolveOwnerBackendCommand with isOwnerExecutionOrTaskBlock so /time-now short-circuit can't hijack deploy/commit/audit prompts (fixes 'The answer is 2019' narrative fallback in the chat path itself)",
    },
    confirm: true,
    confirmText: "CONFIRM_IVX_GITHUB_WRITE",
  }),
});
const j = await r.json();
console.log("status=" + r.status + " commitSha=" + (j?.result?.commitSha ?? "undefined"));
if (!j?.result?.commitSha) console.log("response:", JSON.stringify(j).slice(0, 400));
const sha = j?.result?.commitSha;

if (sha) {
  const dr = await fetch(BASE + "/api/ivx/developer-deploy/action", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
    body: JSON.stringify({ action: "render_trigger_deploy", input: {}, confirm: true, confirmText: "CONFIRM_IVX_RENDER_DEPLOY" }),
  });
  const dj = await dr.json();
  console.log("DEPLOY status=" + dr.status + " deployId=" + dj?.result?.deployId + " status=" + dj?.result?.status);
  console.log("\n=== DONE — poll for LIVE at " + sha + " ===");
}

