// Re-run the controlled deployment test with a unique requestId so we can find
// it in the runtime logs and see exactly which path was taken.
const BASE = "https://api.ivxholding.com";
const token = await Bun.file("/tmp/owner_at").text();

const requestId = "router-fix-verify-" + Date.now();
const prompt = [
  "Controlled deployment test (owner-authorized).",
  "Bump the production-visible version marker IVX_SENIOR_DEV_WORKER_MARKER in backend/services/ivx-senior-developer-worker.ts from 'ivx-senior-developer-worker-2026-07-17' to 'ivx-senior-developer-worker-2026-07-19' (today's date).",
  "Then commit the change to GitHub main, trigger a Render deploy, wait for LIVE, call /health, and confirm the live runtime commit SHA equals GitHub HEAD.",
  "Return verified evidence: commit SHA, deploy ID, /health response, live commit, GitHub HEAD, and whether they match.",
  "This is a harmless version-marker bump — no business logic changes.",
].join(" ");

console.log("requestId:", requestId);
const t0 = Date.now();
const r = await fetch(BASE + "/api/ivx/owner-ai", {
  method: "POST",
  headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
  body: JSON.stringify({ message: prompt, requestId, confirm: true, confirmText: "CONFIRM_IVX_GITHUB_WRITE" }),
});
const elapsed = Date.now() - t0;
const text = await r.text();
console.log("HTTP status:", r.status, "(elapsed " + elapsed + "ms)");

let j;
try { j = JSON.parse(text); } catch { j = { raw: text.slice(0, 2000) }; }
const answer = j.answer || j.response || j.message || (typeof j === "string" ? j : JSON.stringify(j).slice(0, 2000));
console.log("\n=== CHAT ANSWER (first 2000 chars) ===");
console.log(typeof answer === "string" ? answer.slice(0, 2000) : JSON.stringify(answer).slice(0, 2000));

// Also check the routerDebug / selectedIntent / selectedTool fields
console.log("\n=== ROUTING FIELDS ===");
console.log("selectedIntent:", j.selectedIntent || j.routerDebug?.selectedIntent || "N/A");
console.log("selectedTool:", j.selectedTool || j.routerDebug?.selectedTool || "N/A");
console.log("source:", j.source || "N/A");
console.log("provider:", j.provider || "N/A");
console.log("endpoint:", j.endpoint || "N/A");
console.log("model:", j.model || "N/A");

